head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.addTab = function(label, tabId, src) {
    var tabOpt = {
        label: label,
        closable: true
    };
    var contOpt = {
        frameMode: "wframe",
        scope: true,
        src: src,
        alwaysDraw: false,
        title: tabId,
        processMsgFrame: scwin.tabIndex % 2 === 1
    };
    tac_main.addTab(tabId, tabOpt, contOpt);
};
scwin.btn_trigger1_onclick = function(e) {
    var tabId = "sub" + scwin.tabIndex;
    var label = scwin.tabIndex % 2 === 1 ? "내부" : "외부";
    var src = "submission_processMsg_tabControl_wframe_WEFF-543_(WSQ-3971)_sub" + ".xml";
    scwin.addTab(label, tabId, src);
    scwin.tabIndex++;
};
scwin.__isCheck = function() {
    return WebSquare.wUnit.getDomById($p.id + 'tac_main_contents_sub1_body_'+$p.id+'tac_main_contents_sub1_body_wq_processMsgComp') != null;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'btn_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'tac_main_contents_sub1_body_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.__isCheck()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.tabIndex = 1;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
